{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 14,
      "text_ar": "لا يدن مني أحد الآن، ولا يلتمسني مدة أربعين يوماً.",
      "verse": 36
    },
    {
      "chapter": 14,
      "text_ar": "فأخذت الرجال الخمسة كما أمرني، وخرجنا إلى الحقل ومكثنا هناك.",
      "verse": 37
    },
    {
      "chapter": 14,
      "text_ar": "وحدث في اليوم التالي أن صوتاً ناداني قائلاً: افتح يا عزرا فمك واشرب ما أسقيكه.",
      "verse": 38
    },
    {
      "chapter": 14,
      "text_ar": "ففتحت فمي وإذا بكأس مملوءة قدمت لي، وكانت مملوءة بشيء يشبه الماء ولكن لونها كان مثل النار.",
      "verse": 39
    },
    {
      "chapter": 14,
      "text_ar": "أخذت وشربت، ولما شربت نطق قلبي بفهم ونمت الحكمة في صدري لأن روحي حفظت ذاكرتها.",
      "verse": 40
    }
  ]
}
